        /// <remarks/>
        [System.Web.Services.Protocols.SoapRpcMethodAttribute("", RequestNamespace="urn:ProvisionService", ResponseNamespace="urn:ProvisionService")]
        [return: System.Xml.Serialization.SoapElementAttribute("extractReturn")]
        public ExtractData extract(string tablename, int targetid) {
            object[] results = this.Invoke("extract", new object[] {
                        tablename,
                        targetid});
            return ((ExtractData)(results[0]));
        }
        
        /// <remarks/>
        public System.IAsyncResult Beginextract(string tablename, int targetid, System.AsyncCallback callback, object asyncState) {
            return this.BeginInvoke("extract", new object[] {
                        tablename,
                        targetid}, callback, asyncState);
        }
        
        /// <remarks/>
        public ExtractData Endextract(System.IAsyncResult asyncResult) {
            object[] results = this.EndInvoke(asyncResult);
            return ((ExtractData)(results[0]));
        }
        
        /// <remarks/>
        public void extractAsync(string tablename, int targetid) {
            this.extractAsync(tablename, targetid, null);
        }
        
        /// <remarks/>
        public void extractAsync(string tablename, int targetid, object userState) {
            if ((this.extractOperationCompleted == null)) {
                this.extractOperationCompleted = new System.Threading.SendOrPostCallback(this.OnextractOperationCompleted);
            }
            this.InvokeAsync("extract", new object[] {
                        tablename,
                        targetid}, this.extractOperationCompleted, userState);
        }
        
